
class AverageThroughputNotWithinDeviation(Exception):
    """
    Raised when average throughput is not within given deviation.
    """
    pass


class ThroughputMsgsNotFoundInBtslog(Exception):
    """
    Raised when throughput messages could not be found in btslog.
    """
    pass


class InvalidCellType(Exception):
    """
    Raised when given cell_type is different from "nr", "lte", "gsm", "wcdma"
    """
    pass
